package com.myf.product.entity; import jakarta.persistence.*;
@Entity @Table(name="Marca") public class Marca { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="Id") private Long id; @Column(name="Nombre",nullable=false,unique=true) private String nombre; @Column(name="PaisOrigen") private String paisOrigen; @Column(name="Estado",nullable=false) private String estado="ACTIVO"; public Long getId(){return id;} public void setId(Long v){id=v;} public String getNombre(){return nombre;} public void setNombre(String v){nombre=v;} public String getPaisOrigen(){return paisOrigen;} public void setPaisOrigen(String v){paisOrigen=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} }
